let nextLine = 0;
try {
  ({ nextLine } = JSON.parse(await readFile(checkpointPath, 'utf8')));
  if (!Number.isSafeInteger(nextLine) || nextLine < 0) throw new Error('Invalid checkpoint nextLine');
} catch (error) {
  if (error.code === 'ENOENT') {
    nextLine = 0;
  } else if (error instanceof SyntaxError || error.message === 'Invalid checkpoint nextLine') {
    // Keep the corrupt checkpoint as evidence, then replay from the start.
    // Output identities below make the replay append only unseen records.
    await quarantineCheckpoint(checkpointPath);
    nextLine = 0;
  } else {
    throw error;
  }
}

async function quarantineCheckpoint(checkpointPath) {
  const recoveryDir = join(dirname(checkpointPath), 'recovery');
  await mkdir(recoveryDir, { recursive: true });
  let target = join(recoveryDir, 'checkpoint.bad.json');
  // Never overwrite earlier evidence; use a unique name if one already exists.
  const exists = await stat(target).then(() => true, () => false);
  if (exists) target = join(recoveryDir, `checkpoint.bad.${randomUUID()}.json`);
  await rename(checkpointPath, target);
  return target;
}

